(()=>{'use strict';
const KEY='circuit-study-backup-v2',allowed=new Set(['app','quiz','lab','guided','preferences','positions','ui','checklist']);let db=null,queue=Promise.resolve(),status='Loading saved study…',memory={version:2,updated:0,data:{}};
const clone=x=>x===undefined?undefined:JSON.parse(JSON.stringify(x));
function validate(v){if(v?.version!==2||!v.data||typeof v.data!=='object'||Array.isArray(v.data))throw Error('Invalid backup');const data={};for(const[k,value]of Object.entries(v.data))if(allowed.has(k))data[k]=clone(value);return{version:2,updated:Number(v.updated)||0,data};}
try{const raw=localStorage.getItem(KEY);if(raw)memory=validate(JSON.parse(raw));else{const old=JSON.parse(localStorage.getItem('circuitExamV1')||'null');if(old)memory.data.app=old;memory.data.preferences={readingSize:Number(localStorage.getItem('circuit-reading-size'))||22,collapsed:localStorage.getItem('circuit-sidebar-collapsed')==='true',theme:localStorage.getItem('study-site-theme')};}}catch{}
function report(text){status=text;document.querySelectorAll('[data-study-save]').forEach(el=>el.textContent=text);}
function write(changedKey=null){memory.updated=Math.max(Date.now(),memory.updated+1);const snap=clone(memory);let backup=false;try{localStorage.setItem(KEY,JSON.stringify(snap));backup=true;}catch{}report('Saving…');queue=queue.catch(()=>{}).then(()=>new Promise(resolve=>{if(!db){report(backup?'Saved in browser backup · IndexedDB unavailable':'Saving unavailable — export a backup before leaving');resolve();return;}try{const tx=db.transaction('progress','readwrite'),store=tx.objectStore('progress'),read=store.get('study');read.onsuccess=()=>{let merged=snap;try{if(read.result){const canonical=validate(read.result);if(changedKey){merged=canonical;merged.data[changedKey]=snap.data[changedKey];merged.updated=Math.max(canonical.updated,snap.updated);}else if(canonical.updated>snap.updated)merged=canonical;}}catch{}store.put(merged,'study');};tx.oncomplete=()=>{report('Saved on this device · IndexedDB');resolve();};tx.onabort=tx.onerror=()=>{report(backup?'Saved in browser backup · database write failed':'Save failed — export a backup before leaving');resolve();};}catch{report(backup?'Saved in browser backup':'Save failed — export a backup before leaving');resolve();}}));return queue;}
function latestLocal(){try{const raw=localStorage.getItem(KEY);if(raw){const latest=validate(JSON.parse(raw));if(latest.updated>memory.updated)memory=latest;}}catch{}}

function applyPreferences(){const p=memory.data.preferences||{};try{if(p.readingSize)localStorage.setItem('circuit-reading-size',String(p.readingSize));if(typeof p.collapsed==='boolean')localStorage.setItem('circuit-sidebar-collapsed',String(p.collapsed));if(['dark','light'].includes(p.theme)){localStorage.setItem('study-site-theme',p.theme);window.dispatchEvent(new StorageEvent('storage',{key:'study-site-theme',newValue:p.theme}));}}catch{}}
const ready=(async()=>{try{db=await new Promise((resolve,reject)=>{const q=indexedDB.open('circuit-exam-studio',1);q.onupgradeneeded=()=>q.result.createObjectStore('progress');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('Blocked'));});const stored=await new Promise((resolve,reject)=>{const q=db.transaction('progress').objectStore('progress').get('study');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});if(stored){const old=validate(stored);if(old.updated>memory.updated)memory=old;}}catch{}applyPreferences();await write();})();
const api={ready,get:key=>clone(memory.data[key]),set:(key,value)=>{if(!allowed.has(key))throw Error('Unknown study key');latestLocal();memory.data[key]=clone(value);return write(key);},status:()=>status,export:()=>{const blob=new Blob([JSON.stringify(memory,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='circuit-study-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}};window.CircuitStore=api;
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const latest=validate(JSON.parse(e.newValue));if(latest.updated>memory.updated){memory=latest;window.dispatchEvent(new CustomEvent('circuit-study-external'));}}catch{}});
document.addEventListener('click',async e=>{if(e.target.closest('[data-export-study]'))api.export();if(e.target.closest('[data-protect-study]')){try{report(await navigator.storage?.persist?.()?'Persistent storage granted · keep backups too':'Browser did not grant persistence · progress still saves normally');}catch{report('Storage protection unavailable · export a backup');}}if(e.target.closest('.night-toggle,.menu-btn,#reading-smaller,#reading-larger')){const p=api.get('preferences')||{};try{p.theme=localStorage.getItem('study-site-theme');p.readingSize=Number(localStorage.getItem('circuit-reading-size'))||22;p.collapsed=localStorage.getItem('circuit-sidebar-collapsed')==='true';}catch{}api.set('preferences',p);}});
document.addEventListener('change',async e=>{if(!e.target.matches('[data-import-study]'))return;const file=e.target.files?.[0];if(!file)return;try{const imported=validate(JSON.parse(await file.text()));memory=imported;applyPreferences();await write();location.reload();}catch{report('Import failed. Choose an exported circuit-study-progress.json file.');}e.target.value='';});
})();
